examples/src/configuration.cpp<pre><code>// configuration: read a drive's whole configuration, change part of it, and
// make the change permanent.
//
//   configuration &lt;master.dcf&gt; [interface=can0] [node-id=2] [--save]
//
// Without --save the change lasts until the next power cycle.

#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;cstring&gt;
#include &lt;string&gt;

#include "epos4/hardware/Epos4.hpp"

namespace
{

template&lt;typename T&gt;
void Print(const char * name, const std::optional&lt;T&gt; &amp; value, const char * unit = "")
{
  if (value) {
    std::printf("  %-28s %lld %s\n", name, static_cast&lt;long long&gt;(*value), unit);
  } else {
    std::printf("  %-28s (not read)\n", name);
  }
}

}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [--save]\n", argv[0]);
    return 2;
  }
  const bool save = argc &gt; 4 &amp;&amp; std::strcmp(argv[4], "--save") == 0;

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();
  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }
  auto &amp; configurator = motor.GetConfigurator();

  // 1. Read everything. Keeps going past objects that cannot be read (absent
  //    on this hardware or firmware) and returns the first error.
  epos4::configs::Epos4Configuration current;
  if (auto ec = configurator.Refresh(current)) {
    std::printf("some objects could not be read: %s\n", ec.message().c_str());
  }
  std::printf("before:\n");
  Print("limits.maxMotorSpeed", current.limits.maxMotorSpeed, "rpm");
  Print("motionProfile.profileAcceleration", current.motionProfile.profileAcceleration, "rpm/s");
  Print("velocityControl.p", current.velocityControl.p);
  Print("velocityControl.i", current.velocityControl.i);
  Print("motor.nominalCurrent", current.motor.nominalCurrent, "mA");

  // 2. Change only what matters. Unset fields are not written, so the gains
  //    and the motor data above stay exactly as they are.
  epos4::configs::Epos4Configuration change;
  change.limits.maxMotorSpeed = 4000;
  change.motionProfile.profileAcceleration = 3000;
  change.motionProfile.profileDeceleration = 3000;
  change.stopOptions.faultReaction = epos4::signals::FaultReactionOption::kSlowDownOnQuickStopRamp;

  // Validates first and writes nothing if the input mappings clash. Groups
  // that need «Power Disable» are refused while the motor is powered.
  if (auto ec = configurator.Apply(change)) {
    std::printf("apply failed: %s\n", ec.message().c_str());
    return 1;
  }

  // 3. Read back what landed.
  epos4::configs::LimitConfigs limits;
  epos4::configs::MotionProfileConfigs profile;
  configurator.Refresh(limits);
  configurator.Refresh(profile);
  std::printf("after:\n");
  Print("limits.maxMotorSpeed", limits.maxMotorSpeed, "rpm");
  Print("motionProfile.profileAcceleration", profile.profileAcceleration, "rpm/s");

  // 4. Persist across power cycles (0x1010).
  if (save) {
    auto ec = configurator.Save();
    std::printf("save: %s\n", ec ? ec.message().c_str() : "ok");
  }

  bus.Stop();
  return 0;
}
</code></pre>

examples/src/cyclic_position.cpp<pre><code>// cyclic_position: follow a trajectory computed on the master, Cyclic
// Synchronous Position. Here a sine wave around the starting point, in
// degrees at the output.
//
//   cyclic_position &lt;master.dcf&gt; [interface=can0] [node-id=2] [amplitude-deg=20]
//
// The pattern under any trajectory follower: one setpoint per SYNC, the
// drive interpolating between them.

#include &lt;chrono&gt;
#include &lt;cmath&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include &lt;ros2units/units.h&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}

constexpr auto kPeriod = 10ms;
constexpr double kPi = 3.14159265358979323846;
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [amplitude-deg]\n",
      argv[0]);
    return 2;
  }
  const double amplitude = argc &gt; 4 ? std::atof(argv[4]) : 20.0;
  std::signal(SIGINT, OnSignal);

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  motor.SetMechanism(2000, 1.0 / 100.0);   // quadcounts per motor turn, gear ratio
  bus.Start();

  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }
  for (int i = 0; i &lt; 40 &amp;&amp; !motor.IsPdoActive(); ++i) {std::this_thread::sleep_for(50ms);}

  epos4::configs::CyclicConfigs cyclic;
  cyclic.interpolationTimePeriodMs = 10;   // = SYNC period
  motor.GetConfigurator().Apply(cyclic);

  if (!motor.Enable()) {
    std::printf("enable failed: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }
  // Seeds the target with the actual position: the first SYNC holds the axis.
  if (auto ec = motor.EnterCyclicPositionMode()) {
    std::printf("cannot enter CSP: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }

  const auto &amp; mechanism = motor.GetMechanism();
  const units::angle::degree_t origin = mechanism.ToAngle(motor.GetCachedPosition());

  const auto start = std::chrono::steady_clock::now();
  auto next = start;
  for (int cycle = 0; !gStop; ++cycle) {
    const double t = std::chrono::duration&lt;double&gt;(std::chrono::steady_clock::now() - start).count();
    if (t &gt; 4.0) {break;}   // two periods of a 0.5 Hz sine

    const units::angle::degree_t target =
      origin + units::angle::degree_t{amplitude * std::sin(2.0 * kPi * 0.5 * t)};
    motor.StageTargetPosition(target);   // converted to quadcounts, no bus access

    if (!motor.IsCyclicHealthy()) {
      std::printf("axis stopped responding\n");
      break;
    }
    if (cycle % 25 == 0) {
      const units::angle::degree_t actual = mechanism.ToAngle(motor.GetCachedPosition());
      std::printf("  t=%4.2fs  target=%7.2f deg  actual=%7.2f deg\n",
        t, target.value(), actual.value());
    }
    next += kPeriod;
    std::this_thread::sleep_until(next);
  }

  // Back to the origin and hold there for a moment.
  motor.StageTargetPosition(origin);
  std::this_thread::sleep_for(300ms);

  motor.ExitCyclicMode();
  motor.Disable();
  bus.Stop();
  return 0;
}
</code></pre>

examples/src/cyclic_torque.cpp<pre><code>// cyclic_torque: a torque step through Cyclic Synchronous Torque, with a
// velocity limit as protection.
//
//   cyclic_torque &lt;master.dcf&gt; [interface=can0] [node-id=2] [Nm=0.05] [max-rpm=1000]
//
// The torque is at the MOTOR shaft. On a free shaft any torque above
// friction accelerates the motor until it reaches its no-load speed: block
// the output, or keep the time short.

#include &lt;chrono&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include &lt;ros2units/units.h&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}

constexpr auto kPeriod = 10ms;
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [Nm] [max-rpm]\n",
      argv[0]);
    return 2;
  }
  const units::torque::newton_meter_t torque{argc &gt; 4 ? std::atof(argv[4]) : 0.05};
  const int maxRpm = argc &gt; 5 ? std::atoi(argv[5]) : 1000;
  std::signal(SIGINT, OnSignal);

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();

  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }
  for (int i = 0; i &lt; 40 &amp;&amp; !motor.IsPdoActive(); ++i) {std::this_thread::sleep_for(50ms);}

  // Every torque in CST is in thousandths of this. Zero means the motor data
  // (nominal current, torque constant) was never configured.
  auto &amp; rated = motor.GetMotorRatedTorque().Refresh();
  if (rated.GetStatus() || rated.GetValue() == 0) {
    std::printf("motor rated torque unavailable: configure MotorConfigs first\n");
    return 1;
  }
  std::printf("rated torque %.4f Nm, commanding %.4f Nm\n",
    rated.GetValue() / 1e6, torque.value());

  if (!motor.Enable()) {
    std::printf("enable failed: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }
  // Starts at the torque the axis produces now, so a loaded joint is not dropped.
  if (auto ec = motor.EnterCyclicTorqueMode()) {
    std::printf("cannot enter CST: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }

  const auto start = std::chrono::steady_clock::now();
  auto next = start;
  int code = 0;
  for (int cycle = 0; ; ++cycle) {
    const double t = std::chrono::duration&lt;double&gt;(std::chrono::steady_clock::now() - start).count();
    if (gStop || t &gt; 2.0) {break;}

    if (std::abs(motor.GetCachedVelocity()) &gt; maxRpm) {
      std::printf("%d rpm &gt; %d: torque to zero\n", motor.GetCachedVelocity(), maxRpm);
      code = 1;
      break;
    }
    if (!motor.IsCyclicHealthy()) {
      std::printf("axis stopped responding\n");
      code = 1;
      break;
    }

    // In N m: converted with the rated torque read when CST was entered, so
    // there is no bus access here. Raw thousandths work too:
    // StageTargetTorque(std::int16_t{100}).
    motor.StageTargetTorque(torque);

    if (cycle % 20 == 0) {
      std::printf("  t=%4.2fs  torque=%5d per mille  velocity=%6d rpm\n",
        t, motor.GetCachedTorque(), motor.GetCachedVelocity());
    }
    next += kPeriod;
    std::this_thread::sleep_until(next);
  }

  // Zero torque for a few cycles so it reaches the drive before disabling.
  motor.StageTargetTorque(std::int16_t{0});
  std::this_thread::sleep_for(5 * kPeriod);
  motor.ExitCyclicMode();
  motor.Disable();
  bus.Stop();
  return code;
}
</code></pre>

examples/src/cyclic_velocity.cpp<pre><code>// cyclic_velocity: a velocity ramp generated by the master, Cyclic
// Synchronous Velocity. The drive's velocity loop makes the motor follow it
// and brakes actively when the target returns to zero.
//
//   cyclic_velocity &lt;master.dcf&gt; [interface=can0] [node-id=2] [rpm=1000]
//
// The kind of loop a rover wheel runs.

#include &lt;algorithm&gt;
#include &lt;chrono&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}

constexpr auto kPeriod = 10ms;  // the SYNC period of the network (sync_period: 10000 us)
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [rpm]\n", argv[0]);
    return 2;
  }
  const double target = argc &gt; 4 ? std::atof(argv[4]) : 1000.0;  // rpm at the motor
  std::signal(SIGINT, OnSignal);

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();

  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }
  for (int i = 0; i &lt; 40 &amp;&amp; !motor.IsPdoActive(); ++i) {std::this_thread::sleep_for(50ms);}
  if (!motor.IsPdoActive()) {
    std::printf("no PDOs: the cyclic modes need the mapping from the DCF\n");
    return 1;
  }

  // The drive interpolates between setpoints over this window: it must match
  // the SYNC period.
  epos4::configs::CyclicConfigs cyclic;
  cyclic.interpolationTimePeriodMs = 10;
  motor.GetConfigurator().Apply(cyclic);

  if (!motor.Enable()) {
    std::printf("enable failed: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }
  // Starts publishing on every SYNC, from 0 rpm: no jump.
  if (auto ec = motor.EnterCyclicVelocityMode()) {
    std::printf("cannot enter CSV: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }

  // Trapezoid: 0.5 s up, 2 s at speed, 0.5 s down.
  const double ramp = 0.5;
  const double hold = 2.0;
  const auto start = std::chrono::steady_clock::now();
  auto next = start;
  for (int cycle = 0; ; ++cycle) {
    const double t = std::chrono::duration&lt;double&gt;(std::chrono::steady_clock::now() - start).count();
    double factor = std::min(t / ramp, 1.0);
    if (t &gt; ramp + hold) {factor = std::max(0.0, 1.0 - (t - ramp - hold) / ramp);}
    if (gStop) {factor = 0.0;}

    // Lock-free: stores an atomic the bus thread publishes on the next SYNC.
    motor.StageTargetVelocity(static_cast&lt;std::int32_t&gt;(target * factor));

    // Worth checking every cycle: cached values keep reading back even when
    // the bus has gone quiet.
    if (!motor.IsCyclicHealthy()) {
      std::printf("axis stopped responding or left Operation enabled\n");
      break;
    }
    if (cycle % 20 == 0) {
      std::printf("  t=%4.2fs  target=%6.0f  actual=%6d rpm\n",
        t, target * factor, motor.GetCachedVelocity());
    }
    if (factor == 0.0 &amp;&amp; t &gt; ramp) {break;}

    next += kPeriod;
    std::this_thread::sleep_until(next);
  }

  // The target is 0 rpm and the drive is braking: wait for standstill.
  const auto deadline = std::chrono::steady_clock::now() + 2s;
  while (std::abs(motor.GetCachedVelocity()) &gt; 10 &amp;&amp; std::chrono::steady_clock::now() &lt; deadline) {
    std::this_thread::sleep_for(kPeriod);
  }

  motor.ExitCyclicMode();
  motor.Disable();
  bus.Stop();
  return 0;
}
</code></pre>

examples/src/device_info.cpp<pre><code>// device_info: everything worth checking on a drive before moving it.
// Read-only: it never enables the motor or changes a parameter.
//
//   device_info &lt;master.dcf&gt; [interface=can0] [node-id=2]

#include &lt;chrono&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;
#include &lt;vector&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id]\n", argv[0]);
    return 2;
  }
  const std::string dcf = argv[1];
  const std::string iface = argc &gt; 2 ? argv[2] : "can0";
  const auto node = static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2);

  epos4::CanBus bus{{iface, dcf, 1}};
  epos4::Epos4 motor{bus, node};
  bus.Start();

  if (!motor.WaitUntilReady()) {
    std::printf("node %u does not answer: check wiring, bit rate and node-ID\n", node);
    return 1;
  }

  // How the master's boot of the node went. A failed boot still answers SDO.
  for (int i = 0; i &lt; 40 &amp;&amp; motor.GetBootStatus().count == 0; ++i) {
    std::this_thread::sleep_for(50ms);
  }
  const auto boot = motor.GetBootStatus();
  std::printf("boot     : %s", boot.Succeeded() ? "ok" : "FAILED");
  if (boot.errorStatus != 0) {
    std::printf(" ('%c' %s)", boot.errorStatus, boot.what.c_str());
  }
  std::printf("\n");

  epos4::signals::DeviceIdentity identity;
  if (!motor.GetIdentity(identity)) {
    std::printf("identity : %s\n", epos4::signals::Describe(identity).c_str());
  }

  // PDOs arrive once the master has configured the node.
  for (int i = 0; i &lt; 40 &amp;&amp; !motor.IsPdoActive(); ++i) {
    std::this_thread::sleep_for(50ms);
  }
  std::printf("pdo      : %s\n", motor.IsPdoActive() ? "active" : "NOT ACTIVE (SDO only)");

  std::vector&lt;epos4::signals::PdoMismatch&gt; mismatches;
  if (auto ec = motor.CheckPdoMapping(mismatches)) {
    std::printf("mapping  : not checked (%s)\n", ec.message().c_str());
  } else if (mismatches.empty()) {
    std::printf("mapping  : drive and master agree\n");
  } else {
    std::printf("mapping  : %zu differences\n", mismatches.size());
    for (const auto &amp; m : mismatches) {
      std::printf("  %s\n", epos4::signals::Describe(m).c_str());
    }
  }

  std::printf("state    : %s\n",
    epos4::signals::ToString(motor.GetState().Refresh().GetValue()));
  std::printf("mode     : %s\n",
    epos4::signals::ToString(motor.GetOperationMode().Refresh().GetValue()));

  if (motor.IsFaulted()) {
    std::printf("FAULT:\n%s\n", motor.DescribeLastError().c_str());
  }
  std::vector&lt;std::uint16_t&gt; history;
  if (!motor.GetErrorHistory(history) &amp;&amp; !history.empty()) {
    std::printf("history  :");
    for (auto code : history) {std::printf(" 0x%04X", code);}
    std::printf("\n");
  }

  // Several reads at once; with one drive they queue on its SDO channel.
  auto &amp; supply = motor.GetSupplyVoltage();
  auto &amp; temperature = motor.GetPowerStageTemperature();
  auto &amp; current = motor.GetMotorCurrentAveraged();
  epos4::signals::RefreshAll(supply, temperature, current);
  if (epos4::signals::IsAllGood(supply, temperature, current)) {
    std::printf("supply   : %.1f V\n", supply.GetValue().value());
    std::printf("stage    : %.1f degC\n", temperature.GetValue().value());
    std::printf("current  : %.3f A\n", current.GetValue().value());
  }

  epos4::configs::MotorConfigs motorData;
  if (!motor.GetConfigurator().Refresh(motorData)) {
    if (motorData.nominalCurrent) {
      std::printf("nominal  : %.3f A\n", *motorData.nominalCurrent / 1000.0);
    }
    if (motorData.torqueConstant) {
      std::printf("Kt       : %.2f mNm/A\n", *motorData.torqueConstant / 1000.0);
    }
    if (motorData.ratedTorque) {
      std::printf("rated    : %.4f Nm\n", *motorData.ratedTorque / 1e6);
    }
  }

  std::printf("position : %d qc\n", motor.GetPosition().Refresh().GetValue());
  std::printf("velocity : %d rpm\n", motor.GetVelocity().Refresh().GetValue());

  bus.Stop();
  return 0;
}
</code></pre>

examples/src/digital_io.cpp<pre><code>// digital_io: read the inputs, drive a general purpose output, and latch a
// position with the touch probe.
//
//   digital_io &lt;master.dcf&gt; [interface=can0] [node-id=2]

