    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id]\n", argv[0]);
    return 2;
  }
  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();
  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }

  // Inputs, two views: by function (after polarity) and by pin (raw).
  std::printf("negative limit %d, positive limit %d, home %d\n",
    motor.IsNegativeLimitActive(), motor.IsPositiveLimitActive(), motor.IsHomeSwitchActive());
  std::printf("functions 0x%08X, pins 0x%04X\n",
    motor.GetDigitalInputs().Refresh().GetValue(),
    motor.GetDigitalInputPins().Refresh().GetValue());
  std::printf("general purpose A: %d\n",
    motor.IsInputActive(DigitalInputFunction::kGeneralPurposeA));

  // Outputs: assign the function to a pin once, then switch it by function.
  epos4::configs::DigitalOutputConfigs outputs;
  outputs.output1 = DigitalOutputFunction::kGeneralPurposeA;
  if (auto ec = motor.GetConfigurator().Apply(outputs)) {
    std::printf("outputs not configured: %s\n", ec.message().c_str());
  }
  motor.SetDigitalOutput(DigitalOutputFunction::kGeneralPurposeA, true);
  std::printf("output A: %d, pins 0x%04X\n",
    motor.IsOutputActive(DigitalOutputFunction::kGeneralPurposeA),
    motor.GetDigitalOutputPins().Refresh().GetValue());
  motor.SetDigitalOutput(DigitalOutputFunction::kGeneralPurposeA, false);

  // Analog channels, in volts.
  auto &amp; ain1 = motor.GetAnalogInputVoltage(epos4::signals::AnalogInput::k1).Refresh();
  if (!ain1.GetStatus()) {
    std::printf("analog input 1: %.3f V\n", ain1.GetValue().value());
  }
  motor.SetAnalogOutput(epos4::signals::AnalogGeneralPurpose::kA, 1.5_V);

  // Touch probe on the encoder index: latches the exact position of the next
  // index pulse, in the drive. Then turn the motor past it.
  const auto probe = epos4::controls::TouchProbe{}
    .WithTrigger(epos4::controls::TouchProbe::Trigger::kIndexPulse)
    .WithPositiveEdge(true);
  if (auto ec = motor.ArmTouchProbe(probe)) {
    std::printf("touch probe not armed: %s\n", ec.message().c_str());
  } else if (motor.Enable()) {
    motor.SetControl(epos4::controls::ProfilePosition{}.WithPosition(4000).WithRelative(true));
    std::this_thread::sleep_for(2s);

    epos4::signals::TouchProbeState state;
    if (!motor.GetTouchProbe(state) &amp;&amp; state.positiveEdgeStored) {
      std::printf("index latched at %d qc (%u edges)\n",
        state.positiveEdgePosition, unsigned{state.positiveEdgeCount});
    } else {
      std::printf("no edge latched\n");
    }
    motor.DisarmTouchProbe();
    motor.Disable();
  }

  bus.Stop();
  return 0;
}
</code></pre>

examples/src/encoder_setup.cpp<pre><code>// encoder_setup: inspect the feedback configuration, read the resolution the
// drive computed, and report the position in degrees at the output.
//
//   encoder_setup &lt;master.dcf&gt; [interface=can0] [node-id=2] [gear-ratio=0.01]
//
// Read-only. Writing encoder configuration (Encoder::Apply) needs the motor
// unpowered and clears the homing reference.

#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;

#include &lt;ros2units/units.h&gt;

#include "epos4/hardware/Encoder.hpp"
#include "epos4/hardware/Epos4.hpp"

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [gear-ratio]\n",
      argv[0]);
    return 2;
  }
  const double gearRatio = argc &gt; 4 ? std::atof(argv[4]) : 1.0 / 100.0;

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();
  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }
  auto &amp; encoder = motor.GetEncoder();

  // Which sensor sits in each slot (0x3000:01), and the main resolution.
  epos4::configs::SensorsConfigs sensors;
  if (auto ec = encoder.Refresh(sensors)) {
    std::printf("sensors not read: %s\n", ec.message().c_str());
  } else {
    std::printf("sensor 1: 0x%02X  sensor 2: 0x%02X  sensor 3: 0x%02X\n",
      static_cast&lt;unsigned&gt;(sensors.sensor1.value_or(epos4::configs::Sensor1Type::kNone)),
      static_cast&lt;unsigned&gt;(sensors.sensor2.value_or(epos4::configs::Sensor2Type::kNone)),
      static_cast&lt;unsigned&gt;(sensors.sensor3.value_or(epos4::configs::Sensor3Type::kNone)));
    if (sensors.mainSensorResolution) {
      std::printf("main sensor resolution: %u qc/rev\n", *sensors.mainSensorResolution);
    }
  }

  // The incremental encoder 1 settings.
  epos4::configs::DigitalIncrementalEncoderConfigs incremental;
  incremental.encoderNumber = 1;
  if (!encoder.Refresh(incremental) &amp;&amp; incremental.pulsesPerRevolution) {
    std::printf("encoder 1: %u pulses/rev = %u qc/rev\n",
      *incremental.pulsesPerRevolution,
      epos4::Encoder::QuadCountsPerRevolution(*incremental.pulsesPerRevolution));
  }

  // Take the resolution from the drive; only the gear ratio is ours. If the
  // drive does not report one, compute it from the encoder's pulses.
  if (auto ec = encoder.SetMechanismFromDevice(gearRatio)) {
    if (!incremental.pulsesPerRevolution) {
      std::printf("mechanism not set: %s\n", ec.message().c_str());
      return 1;
    }
    encoder.SetMechanism(
      epos4::Encoder::QuadCountsPerRevolution(*incremental.pulsesPerRevolution), gearRatio);
    std::printf("resolution from the encoder pulses: %u qc/rev\n",
      encoder.GetMechanism().GetQuadCountsPerRevolution());
  }
  if (auto angle = encoder.GetAngle()) {
    const units::angle::degree_t degrees = *angle;
    std::printf("output angle: %.3f deg\n", degrees.value());
  }
  if (auto velocity = encoder.GetAngularVelocity()) {
    std::printf("output velocity: %.3f rpm\n", velocity-&gt;value());
  }

  bus.Stop();
  return 0;
}
</code></pre>

examples/src/fault_monitor.cpp<pre><code>// fault_monitor: react to faults as they happen, and recover from them.
//
//   fault_monitor &lt;master.dcf&gt; [interface=can0] [node-id=2] [seconds=10]
//
// Registers an emergency callback, polls telemetry at 2 Hz, and clears a
// fault when one arrives - the loop a base station status panel runs.

#include &lt;atomic&gt;
#include &lt;chrono&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include "epos4/hardware/Epos4.hpp"
#include "epos4/signals/Errors.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [seconds]\n", argv[0]);
    return 2;
  }
  const double seconds = argc &gt; 4 ? std::atof(argv[4]) : 10.0;
  std::signal(SIGINT, OnSignal);

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};

  // Runs on the CANopen thread the moment an EMCY frame arrives: keep it
  // short, never block, never call back into the device. Here it only flags
  // the main loop. May be registered before Start().
  std::atomic&lt;bool&gt; emergency{false};
  motor.SetEmergencyCallback(
    [&amp;emergency](const epos4::signals::EmergencyMessage &amp; message) {
      std::printf("EMCY: %s\n", epos4::signals::Describe(message).c_str());
      if (message.errorCode != 0 &amp;&amp; !epos4::signals::IsWarning(message.errorCode)) {
        emergency = true;
      }
    });

  bus.Start();
  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }

  auto &amp; voltage = motor.GetSupplyVoltage();
  auto &amp; temperature = motor.GetPowerStageTemperature();
  auto &amp; i2t = motor.GetMotorI2tPercent();

  const auto end = std::chrono::steady_clock::now() +
    std::chrono::duration_cast&lt;std::chrono::steady_clock::duration&gt;(
    std::chrono::duration&lt;double&gt;(seconds));
  while (!gStop &amp;&amp; std::chrono::steady_clock::now() &lt; end) {
    epos4::signals::RefreshAll(voltage, temperature, i2t);
    std::printf("%.1f V  %.1f degC  I2t %u %%  last EMCY 0x%04X\n",
      voltage.GetValue().value(), temperature.GetValue().value(),
      unsigned{i2t.GetValue()}, motor.GetCachedErrorCode());

    if (emergency.exchange(false) || motor.IsFaulted()) {
      // Cause, effect and recovery from chapter 7 of the firmware manual.
      std::printf("%s\n", motor.DescribeLastError().c_str());

      const std::uint16_t code = motor.GetErrorCode().Refresh().GetValue();
      if (epos4::signals::ClearsPosition(code)) {
        std::printf("this fault clears the position: home again before moving\n");
      }
      // Sends the NMT reset communication first when the fault needs it
      // (a lost heartbeat, CAN passive). False if the cause is still there.
      std::printf("clearing... %s\n", motor.ClearFault() ? "ok" : "still faulted");
    }
    std::this_thread::sleep_for(500ms);
  }

  bus.Stop();
  return 0;
}
</code></pre>

examples/src/homing.cpp<pre><code>// homing: give an incremental encoder an absolute zero.
//
//   homing &lt;master.dcf&gt; [interface=can0] [node-id=2]
//
// Maps the limit switches to their inputs, configures the homing run and
// homes on the negative limit switch. Then shows SetPosition(), which
// declares a position without moving.

#include &lt;chrono&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;vector&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;
using epos4::signals::DigitalInputFunction;
using epos4::signals::HomingMethod;

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id]\n", argv[0]);
    return 2;
  }
  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();

  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }

  // Which methods this firmware implements.
  std::vector&lt;HomingMethod&gt; supported;
  if (!motor.GetSupportedHomingMethods(supported)) {
    std::printf("supported:");
    for (auto m : supported) {std::printf(" %d", static_cast&lt;int&gt;(m));}
    std::printf("\n");
  }

  // A switch that is wired but not mapped does nothing. These are also the
  // drive's defaults (Table 6-130); Apply() refuses a function mapped twice.
  epos4::configs::DigitalInputConfigs inputs;
  inputs.input1 = DigitalInputFunction::kNegativeLimitSwitch;
  inputs.input2 = DigitalInputFunction::kPositiveLimitSwitch;
  inputs.input3 = DigitalInputFunction::kHomeSwitch;

  epos4::configs::HomingConfigs homing;
  homing.speedForSwitchSearch = 500;    // rpm
  homing.speedForZeroSearch = 100;      // rpm
  homing.acceleration = 2000;           // rpm/s
  homing.homeOffsetMoveDistance = 0;    // qc to move away from the switch afterwards
  homing.homePosition = 0;              // the position assigned to home

  if (auto ec = motor.GetConfigurator().Apply(inputs)) {
    std::printf("inputs not applied: %s\n", ec.message().c_str());
    return 1;
  }
  if (auto ec = motor.GetConfigurator().Apply(homing)) {
    std::printf("homing not applied: %s\n", ec.message().c_str());
    return 1;
  }

  // A limit switch already active before the run usually means an inverted
  // polarity, not an axis sitting at the end stop.
  std::printf("negative limit active: %s\n", motor.IsNegativeLimitActive() ? "yes" : "no");

  if (!motor.Enable()) {
    std::printf("enable failed: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }

  // Blocks until the run ends. Refuses a method whose switch is not mapped,
  // or that the drive does not list, before anything moves.
  const bool homed = motor.Home(
    epos4::controls::Homing{}.WithMethod(HomingMethod::kNegativeLimitSwitch), 30s);
  std::printf("homing %s, position %d qc, referenced: %s\n",
    homed ? "attained" : "FAILED",
    motor.GetPosition().Refresh().GetValue(),
    motor.IsPositionReferenced().GetValueRefreshed() ? "yes" : "no");
  if (!homed &amp;&amp; motor.HasHomingError().GetValueRefreshed()) {
    std::printf("the drive reports a homing error\n");
  }

  // Declare "here is 1000" without moving (homing method 37). The homing
  // configuration is restored afterwards.
  if (auto ec = motor.SetPosition(1000)) {
    std::printf("SetPosition failed: %s\n", ec.message().c_str());
  } else {
    std::printf("position is now %d qc\n", motor.GetPosition().Refresh().GetValue());
  }

  motor.Disable();
  bus.Stop();
  return homed ? 0 : 1;
}
</code></pre>

examples/src/multi_drive.cpp<pre><code>// multi_drive: several drives on one bus, commanded together.
//
//   multi_drive &lt;master.dcf&gt; [interface=can0]
//
// Uses config/two_drives/bus.yml: nodes 2 and 3, a left and a right wheel.
// Both receive their setpoint in the same SYNC, so they act on the same
// instant.

#include &lt;array&gt;
#include &lt;chrono&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}

constexpr auto kPeriod = 10ms;
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface]\n", argv[0]);
    return 2;
  }
  std::signal(SIGINT, OnSignal);

  // One bus, one master, one socket - shared by every device on it.
  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};

  // Every device declared before Start().
  epos4::Epos4 left{bus, 2};
  epos4::Epos4 right{bus, 3};
  std::array&lt;epos4::Epos4 *, 2&gt; wheels{&amp;left, &amp;right};

  bus.Start();

  for (auto * wheel : wheels) {
    if (!wheel-&gt;WaitUntilReady()) {
      std::printf("node %u does not answer\n", wheel-&gt;GetNodeId());
      return 1;
    }
  }

  // Diagnostics from every drive at once: SDO reads to different nodes
  // overlap, so this costs about one round trip instead of two.
  epos4::signals::RefreshAll(left.GetSupplyVoltage(), right.GetSupplyVoltage());
  std::printf("supply: left %.1f V, right %.1f V\n",
    left.GetSupplyVoltage().GetValue().value(), right.GetSupplyVoltage().GetValue().value());

  for (auto * wheel : wheels) {
    if (!wheel-&gt;Enable() || wheel-&gt;EnterCyclicVelocityMode()) {
      std::printf("node %u: %s\n", wheel-&gt;GetNodeId(), wheel-&gt;DescribeLastError().c_str());
      for (auto * w : wheels) {w-&gt;Disable();}
      return 1;
    }
  }

  // Drive forward, then turn in place, then stop.
  const auto start = std::chrono::steady_clock::now();
  auto next = start;
  for (int cycle = 0; !gStop; ++cycle) {
    const double t = std::chrono::duration&lt;double&gt;(std::chrono::steady_clock::now() - start).count();
    std::int32_t l = 0;
    std::int32_t r = 0;
    if (t &lt; 2.0) {l = 800; r = 800;}            // forward
    else if (t &lt; 4.0) {l = 600; r = -600;}      // turn in place
    else {break;}

    left.StageTargetVelocity(l);
    right.StageTargetVelocity(r);

    if (!left.IsCyclicHealthy() || !right.IsCyclicHealthy()) {
      std::printf("a wheel stopped responding\n");
      break;
    }
    if (cycle % 50 == 0) {
      std::printf("  t=%4.2fs  left %5d rpm  right %5d rpm\n",
        t, left.GetCachedVelocity(), right.GetCachedVelocity());
    }
    next += kPeriod;
    std::this_thread::sleep_until(next);
  }

  for (auto * wheel : wheels) {wheel-&gt;StageTargetVelocity(0);}
  std::this_thread::sleep_for(500ms);
  for (auto * wheel : wheels) {
    wheel-&gt;ExitCyclicMode();
    wheel-&gt;Disable();
  }
  bus.Stop();
  return 0;
}
</code></pre>

examples/src/profile_position.cpp<pre><code>// profile_position: point-to-point moves, with the drive generating the ramp.
//
//   profile_position &lt;master.dcf&gt; [interface=can0] [node-id=2]
//
// Moves to an absolute position in quadcounts, then a relative move given as
// an angle at the output, then back to where it started.

#include &lt;chrono&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include &lt;ros2units/units.h&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;
using namespace units::literals;

namespace
{

// Target reached can still be set from the previous move when a new one is
// commanded: wait for it to drop, then for it to come back.
bool WaitForTarget(epos4::Epos4 &amp; motor, std::chrono::seconds timeout)
{
  for (int i = 0; i &lt; 20 &amp;&amp; motor.IsTargetReached().GetValueRefreshed(); ++i) {
    std::this_thread::sleep_for(20ms);
  }
  const auto deadline = std::chrono::steady_clock::now() + timeout;
  while (std::chrono::steady_clock::now() &lt; deadline) {
    if (motor.IsTargetReached().GetValueRefreshed()) {
      return true;
    }
    if (motor.IsFaulted()) {
      std::printf("fault during the move:\n%s\n", motor.DescribeLastError().c_str());
      return false;
    }
    std::this_thread::sleep_for(10ms);
  }
  return false;
}

}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id]\n", argv[0]);
    return 2;
  }
  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};

  // 500-pulse encoder (2000 quadcounts per motor turn) behind a 1:100 gearbox.
  // Only needed for the requests given as quantities.
  motor.SetMechanism(2000, 1.0 / 100.0);

  bus.Start();
  if (!motor.WaitUntilReady()) {
    std::printf("no answer from the drive\n");
    return 1;
  }

  // The defaults every move uses unless the request overrides them.
  epos4::configs::MotionProfileConfigs profile;
  profile.profileVelocity = 1000;       // rpm
  profile.profileAcceleration = 5000;   // rpm/s
  profile.profileDeceleration = 5000;   // rpm/s
  if (auto ec = motor.GetConfigurator().Apply(profile)) {
    std::printf("profile not applied: %s\n", ec.message().c_str());
    return 1;
  }

  if (!motor.Enable()) {
    std::printf("enable failed: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }
  const std::int32_t start = motor.GetPosition().Refresh().GetValue();

  // 1. Absolute, in raw drive units.
  auto ec = motor.SetControl(epos4::controls::ProfilePosition{}
                               .WithPosition(start + 10000));
  if (ec || !WaitForTarget(motor, 30s)) {
    std::printf("move 1 failed: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }
  std::printf("move 1 done at %d qc\n", motor.GetPosition().Refresh().GetValue());

  // 2. Relative, as an angle at the output, with its own speed.
  ec = motor.SetControl(epos4::controls::ProfilePosition{}
                          .WithPosition(90_deg)     // 90 degrees at the joint
                          .WithVelocity(1500)       // rpm at the motor
                          .WithRelative(true));
  if (ec || !WaitForTarget(motor, 60s)) {
    std::printf("move 2 failed: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }
  std::printf("move 2 done at %d qc\n", motor.GetPosition().Refresh().GetValue());

  // 3. Back to the start.
  ec = motor.SetControl(epos4::controls::ProfilePosition{}.WithPosition(start));
  if (ec || !WaitForTarget(motor, 60s)) {
    std::printf("move 3 failed: %s\n", ec.message().c_str());
  } else {
    std::printf("back at %d qc\n", motor.GetPosition().Refresh().GetValue());
  }

  motor.Disable();
  bus.Stop();
  return 0;
}
</code></pre>

examples/src/profile_velocity.cpp<pre><code>// profile_velocity: spin at a velocity, with the drive generating the ramp.
//
//   profile_velocity &lt;master.dcf&gt; [interface=can0] [node-id=2] [rpm=1000] [seconds=3]
//
// epos4_sim does not model Profile Velocity Mode: run this on hardware.

#include &lt;chrono&gt;
#include &lt;csignal&gt;
#include &lt;cstdio&gt;
#include &lt;cstdlib&gt;
#include &lt;string&gt;
#include &lt;thread&gt;

#include "epos4/hardware/Epos4.hpp"

using namespace std::chrono_literals;

namespace
{
volatile std::sig_atomic_t gStop = 0;
void OnSignal(int) {gStop = 1;}
}  // namespace

int main(int argc, char ** argv)
{
  if (argc &lt; 2) {
    std::fprintf(stderr, "usage: %s &lt;master.dcf&gt; [interface] [node-id] [rpm] [seconds]\n",
      argv[0]);
    return 2;
  }
  const int rpm = argc &gt; 4 ? std::atoi(argv[4]) : 1000;
  const double seconds = argc &gt; 5 ? std::atof(argv[5]) : 3.0;
  std::signal(SIGINT, OnSignal);

  epos4::CanBus bus{{argc &gt; 2 ? argv[2] : "can0", argv[1], 1}};
  epos4::Epos4 motor{bus, static_cast&lt;std::uint8_t&gt;(argc &gt; 3 ? std::atoi(argv[3]) : 2)};
  bus.Start();

  if (!motor.WaitUntilReady() || !motor.Enable()) {
    std::printf("not ready: %s\n", motor.DescribeLastError().c_str());
    return 1;
  }

  // Reaches rpm in rpm / acceleration seconds: 1000 rpm at 2000 rpm/s is 0.5 s.
  auto ec = motor.SetControl(epos4::controls::ProfileVelocity{}
                               .WithVelocity(rpm)
                               .WithAcceleration(2000)
                               .WithDeceleration(2000));
  if (ec) {
    std::printf("rejected: %s\n", ec.message().c_str());
    motor.Disable();
    return 1;
  }

  const auto end = std::chrono::steady_clock::now() +
    std::chrono::duration_cast&lt;std::chrono::steady_clock::duration&gt;(
    std::chrono::duration&lt;double&gt;(seconds));
  while (!gStop &amp;&amp; std::chrono::steady_clock::now() &lt; end) {
    std::printf("  velocity %5d rpm  current %.3f A\n",
      motor.GetVelocity().Refresh().GetValue(),
      motor.GetMotorCurrentAveraged().Refresh().GetValue().value());
    std::this_thread::sleep_for(200ms);
  }

  // Back to zero on the same deceleration ramp, then wait for standstill.
  motor.SetControl(epos4::controls::ProfileVelocity{}.WithVelocity(0));
  for (int i = 0; i &lt; 100 &amp;&amp; !motor.IsAtZeroSpeed().GetValueRefreshed(); ++i) {
    std::this_thread::sleep_for(20ms);
  }

  motor.Disable();
  bus.Stop();
  return 0;
}
